def min_stack_ops(ops):
    stack = []
    results = []
    for op in ops:
        name = op[0]
        if name == 'push':
            value = op[1]
            cur_min = value if not stack else min(value, stack[-1][1])
            stack.append((value, cur_min))
        elif name == 'pop':
            if stack:
                stack.pop()
        elif name == 'top':
            results.append(stack[-1][0])
        elif name == 'getMin':
            results.append(stack[-1][1])
    return results
